// The everyday case. A tab loses its connection, the server lets go of the notebook and later builds it again from the file, and the tab reconnects. Everything the tab says reaches the server. Many of the stories below vary this one.
test(
  ...story(
      {
        "id": "A",
        "group": "handshake",
        "title": "Control: a tab reconnects to a notebook the server rebuilt",
        "requires": [
          "releaseRoom"
        ]
      },
    async s => {
      await s.notebook(["c0", "c1", "c2"]);
      const tab = s.tab("tab");

      await s.step(1, "Your tab", "opens the notebook", async () => {
        await tab.open();
        await s.expectTab(tab, ["c0", "c1", "c2"]);
      });
      await s.step(2, "Your tab", "loses its connection (laptop lid closed)", async () => {
        await tab.goOffline();
      });
      await s.step(3, "Server", "lets go of the notebook, then builds it again from the file", async () => {
        await s.releaseRoom();
      });
      await s.step(4, "Your tab", "reconnects and sends its answer; the answer arrives", async () => {
        await tab.goOnline();
      });
      await s.step(5, "Your tab", "the connection drops once more", async () => {
        await tab.goOffline();
      });
      await s.step(6, "Your tab", "reconnects again", async () => {
        await tab.goOnline();
      });

      await s.ends([
        { label: "As the story ends", ends: { tab: ["c0", "c1", "c2"], server: ["c0", "c1", "c2"], file: ["c0", "c1", "c2"] } },
      ]);
    }
  )
);

