// Tabs A and B and a collaborator W work in one notebook. A leaves early, so B holds more of what W did than A does. Then the server lets go of the notebook and builds it again, and A comes back first, B second.
test(
  ...story(
      {
        "id": "H2",
        "group": "handshake",
        "title": "Two out-of-date tabs hold different amounts of the same session",
        "requires": [
          "releaseRoom"
        ]
      },
    async s => {
      await s.notebook(["c0", "c1", "c2"]);
      const tab = s.tab("tab");
      const tab2 = s.tab("tab2");
      const tab3 = s.tab("tab3");

      await s.step(1, "Tab A + Tab B + Collaborator W", "A, B and W open the notebook", async () => {
        await tab.open();
        await s.expectTab(tab, ["c0", "c1", "c2"]);
        await tab2.open();
        await s.expectTab(tab2, ["c0", "c1", "c2"]);
        await tab3.open();
        await s.expectTab(tab3, ["c0", "c1", "c2"]);
      });
      await s.step(2, "Collaborator W", "W adds a cell “X-1”", async () => {
        await tab3.addCell(3, "X-1");
        await s.settle(tab3);
        await s.expectTab(tab3, ["c0", "c1", "c2", "X-1"]);
      });
      await s.step(3, "Tab A + Tab B", "A and B receive X-1", async () => {
        await s.expectTabEventually(tab, ["c0", "c1", "c2", "X-1"]);
        await s.expectTabEventually(tab2, ["c0", "c1", "c2", "X-1"]);
      });
      await s.step(4, "Tab A", "A goes away (laptop closed)", async () => {
        await tab.goOffline();
      });
      await s.step(5, "Collaborator W", "W adds another cell “X-2”", async () => {
        await tab3.addCell(4, "X-2");
        await s.settle(tab3);
        await s.expectTab(tab3, ["c0", "c1", "c2", "X-1", "X-2"]);
      });
      await s.step(6, "Tab B", "only B receives X-2: B now holds more of W's work than A", async () => {
        await s.expectTabEventually(tab2, ["c0", "c1", "c2", "X-1", "X-2"]);
      });
      await s.step(7, "Tab B + Collaborator W", "B and W close their tabs", async () => {
        await tab2.goOffline(); // it goes away and, later in the story, comes back: the tab stays open
        await tab3.close();
      });
      await s.step(8, "File on disk", "holds all five cells", async () => {
        // nothing for a test to do: the storyboard states what is so
      });
      await s.step(9, "Server", "lets go of the notebook, then builds it again from the file", async () => {
        await s.releaseRoom();
      });
      await s.step(10, "Tab A", "A comes back first", async () => {
        await tab.goOnline();
      });
      await s.step(11, "Tab B", "B comes back second; it holds a longer piece of W's work than A did", async () => {
        await tab2.goOnline();
      });

      await s.ends([
        { label: "As the story ends", ends: { tab: ["c0", "c1", "c2", "X-1", "X-2"], tab2: ["c0", "c1", "c2", "X-1", "X-2"], server: ["c0", "c1", "c2", "X-1", "X-2"], file: ["c0", "c1", "c2", "X-1", "X-2"] } },
      ]);
    }
  )
);

